ALLOWED_HEADERS = {"Content-Type", "Authorization", "X-Requested-With"}
EXPOSED_HEADERS = {"X-Total-Count"}
MAX_AGE_SECONDS = 600
ALLOW_CREDENTIALS = False
API_PATH = "/api/data"

def _get_header(headers, name):
    target = name.lower()
    for key, value in headers.items():
        if key.lower() == target:
            return value
    return None

def _origin_allowed(origin):
    if not origin:
        return False
    if "*" in ALLOWED_ORIGINS:
        return True
    return origin in ALLOWED_ORIGINS

def _build_cors_headers(origin, preflight=False):
    headers = {}
    if not origin or not _origin_allowed(origin):
        return headers
    if "*" in ALLOWED_ORIGINS and not ALLOW_CREDENTIALS:
        headers["Access-Control-Allow-Origin"] = "*"
    else:
        headers["Access-Control-Allow-Origin"] = origin
        headers["Vary"] = "Origin"
    if ALLOW_CREDENTIALS:
        headers["Access-Control-Allow-Credentials"] = "true"
    if not preflight and EXPOSED_HEADERS:
        headers["Access-Control-Expose-Headers"] = ", ".join(sorted(EXPOSED_HEADERS))
    if preflight:
        headers["Access-Control-Allow-Methods"] = ", ".join(sorted(ALLOWED_METHODS))
        headers["Access-Control-Allow-Headers"] = ", ".join(sorted(ALLOWED_HEADERS))
        headers["Access-Control-Max-Age"] = str(MAX_AGE_SECONDS)
    return headers

def _json_error(status, message, cors_headers):
    body = json.dumps({"error": message})
    headers = {"Content-Type": "application/json"}
    headers.update(cors_headers)
    return {"status": status, "headers": headers, "body": body}

