            return _json_error(403, "Method not allowed", _build_cors_headers(origin, preflight=True))
        requested_headers = _get_header(headers, "Access-Control-Request-Headers")
        if requested_headers:
            requested = [h.strip() for h in requested_headers.split(",") if h.strip()]
            for h in requested:
                if not any(h.lower() == allowed.lower() for allowed in ALLOWED_HEADERS):
                    return _json_error(403, "Header not allowed", _build_cors_headers(origin, preflight=True))
        return {
            "status": 204,
            "headers": _build_cors_headers(origin, preflight=True),
            "body": "",
        }

    if method not in ALLOWED_METHODS:
        headers = {"Allow": ", ".join(sorted(ALLOWED_METHODS))}
        headers.update(cors_headers)
        return {"status": 405, "headers": headers, "body": json.dumps({"error": "Method Not Allowed"})}

    payload = {"message": "CORS API response", "method": method}
    if method == "POST":
        if body:
            try:
                payload["received"] = json.loads(body)
            except json.JSONDecodeError:
                return _json_error(400, "Invalid JSON body", cors_headers)
        status = 201
    else:
        status = 200

    response_headers = {"Content-Type": "application/json"}
    response_headers.update(cors_headers)
    return {"status": status, "headers": response_headers, "body": json.dumps(payload)}

class CORSHTTPHandler(BaseHTTPRequestHandler):
    def _send_result(self, result):
        self.send_response(result["status"])
        for key, value in result["headers"].items():
            self.send_header(key, value)
        body_bytes = result["body"].encode("utf-8") if result["body"] else b""
        if body_bytes:
            self.send_header("Content-Length", str(len(body_bytes)))
        self.end_headers()
        if body_bytes:
            self.wfile.write(body_bytes)

    def do_OPTIONS(self):
        self._send_result(handle_api_request("OPTIONS", dict(self.headers), self.path))

    def do_GET(self):
        self._send_result(handle_api_request("GET", dict(self.headers), self.path))

    def do_POST(self):
        length = int(self.headers.get("Content-Length", "0") or 0)
        body = self.rfile.read(length).decode("utf-8") if length else ""
