        headers["Access-Control-Allow-Methods"] = ", ".join(sorted(ALLOWED_METHODS))
        headers["Access-Control-Allow-Headers"] = ", ".join(sorted(ALLOWED_HEADERS))
        headers["Access-Control-Max-Age"] = str(MAX_AGE_SECONDS)
    return headers

def _json_error(status, message, cors_headers):
    body = json.dumps({"error": message})
    headers = {"Content-Type": "application/json"}
    headers.update(cors_headers)
    return {"status": status, "headers": headers, "body": body}

def handle_api_request(method, headers, path, body=None):
    method = method.upper()
    request_path = urlparse(path).path
    origin = _get_header(headers, "Origin")
    cors_headers = _build_cors_headers(origin)

    if request_path != API_PATH:
        return _json_error(404, "Not Found", cors_headers)

    if method == "OPTIONS":
        if not origin:
            return _json_error(400, "Missing Origin header for preflight request", {})
        if not _origin_allowed(origin):
            return _json_error(403, "Origin not allowed", {})
        requested_method = _get_header(headers, "Access-Control-Request-Method")
        if not requested_method:
            return _json_error(400, "Missing Access-Control-Request-Method header", _build_cors_headers(origin, preflight=True))
        if requested_method.upper() not in ALLOWED_METHODS:
            return _json_error(403, "Method not allowed", _build_cors_headers(origin, preflight=True))
        requested_headers = _get_header(headers, "Access-Control-Request-Headers")
        if requested_headers:
            requested = [h.strip() for h in requested_headers.split(",") if h.strip()]
            for h in requested:
                if not any(h.lower() == allowed.lower() for allowed in ALLOWED_HEADERS):
                    return _json_error(403, "Header not allowed", _build_cors_headers(origin, preflight=True))
        return {
            "status": 204,
            "headers": _build_cors_headers(origin, preflight=True),
            "body": "",
        }

    if method not in ALLOWED_METHODS:
        headers = {"Allow": ", ".join(sorted(ALLOWED_METHODS))}
        headers.update(cors_headers)
        return {"status": 405, "headers": headers, "body": json.dumps({"error": "Method Not Allowed"})}

    payload = {"message": "CORS API response", "method": method}
    if method == "POST":
        if body:
            try:
                payload["received"] = json.loads(body)
            except json.JSONDecodeError:
                return _json_error(400, "Invalid JSON body", cors_headers)
        status = 201
    else:
        status = 200

    response_headers = {"Content-Type": "application/json"}
    response_headers.update(cors_headers)
    return {"status": status, "headers": response_headers, "body": json.dumps(payload)}

class CORSHTTPHandler(BaseHTTPRequestHandler):
    def _send_result(self, result):
        self.send_response(result["status"])
        for key, value in result["headers"].items():
            self.send_header(key, value)
        body_bytes = result["body"].encode("utf-8") if result["body"] else b""
        if body_bytes:
            self.send_header("Content-Length", str(len(body_bytes)))
        self.end_headers()
        if body_bytes:
            self.wfile.write(body_bytes)

    def do_OPTIONS(self):
        self._send_result(handle_api_request("OPTIONS", dict(self.headers), self.path))

    def do_GET(self):
        self._send_result(handle_api_request("GET", dict(self.headers), self.path))

    def do_POST(self):
        length = int(self.headers.get("Content-Length", "0") or 0)
        body = self.rfile.read(length).decode("utf-8") if length else ""
        self._send_result(handle_api_request("POST", dict(self.headers), self.path, body))

    def log_message(self, format, *args):
        return

def run_server(host="127.0.0.1", port=8000):
    server = HTTPServer((host, port), CORSHTTPHandler)
    print(f"CORS API running at http://{host}:{port}{API_PATH}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

if __name__ == "__main__":
    run_server()

